 const origen=Array.isArray(m&&m.camaras)?m.camaras:[];
 const camaras=origen.filter(c=>c&&String(c.ID_Camara||'').trim()&&String(c.Codigo||c.Nombre||'').trim()&&!['INACTIVA','INACTIVO','DESACTIVADA','DESACTIVADO'].includes(String(c.Estado||'').trim().toUpperCase()));
 this.estado.mapa=Object.assign({},m,{camaras});
 let siguienteX=0;
