  const tieneX=c.Mapa_Columna!==null&&c.Mapa_Columna!==undefined&&String(c.Mapa_Columna).trim()!=='';
  const ancho=Math.max(1,Math.floor(this.numeroMapa(c.Mapa_Ancho,1)));
