colisionesMapa(){const d=this.estado.mapaBorrador||[],ids=new Set();for(let i=0;i<d.length;i++)for(let j=i+1;j<d.length;j++)if(d[i].x<d[j].x+d[j].ancho&&d[i].x+d[i].ancho>d[j].x&&d[i].y<d[j].y+d[j].alto&&d[i].y+d[i].alto>d[j].y){ids.add(String(d[i].camara.ID_Camara));ids.add(String(d[j].camara.ID_Camara))}return ids},
