accionMapa(accion){if(accion==='editar'){this.estado.mapaAreaOriginal={x:this.estado.mapaAreaX,y:this.estado.mapaAreaY,altura:this.estado.mapaAltura};this.estado.mapaEdicion=true;return this.pintarMapa()}if(accion==='cancelar'){this.estado.mapaBorrador=(this.estado.mapaOriginal||[]).map(d=>({...d}));const anterior=this.estado.mapaAreaOriginal||{};this.estado.mapaAreaX=anterior.x||0;this.estado.mapaAreaY=anterior.y||0;this.estado.mapaAltura=anterior.altura||0;this.guardarAreaMapa();this.estado.mapaEdicion=false;return this.pintarMapa()}if(accion==='guardar')return this.guardarMapa().catch(e=>this.error(e));if(accion.startsWith('columnas-')||accion.startsWith('filas-')||accion.startsWith('altura-')||accion==='area-ajustar')return this.modificarAreaMapa(accion);this.estado.mapaZoom=accion==='ajustar'?100:Math.max(55,Math.min(220,(this.estado.mapaZoom||100)+(accion==='mas'?15:-15)));this.pintarMapa()},
